import { lazy } from 'react';
import { Building2 as IcBuilding2, GitBranch as IcGitBranch, Network as IcNetwork, Palette as IcPalette } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Company Setup — hub page for the Settings menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'CompanySetup'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const CompanyProfile = lazy(() => import('../../settings/pages/CompanyProfile'));
const BranchManagement = lazy(() => import('./BranchManagement'));
const OrganizationSetup = lazy(() => import('../../orgchart/pages/OrganizationSetup'));
const BrandVault = lazy(() => import('./BrandVault'));

export const TABS = [
  { id: 'profile', label: 'Company Profile', icon: IcBuilding2, page: 'CompanyProfile', Component: CompanyProfile },
  { id: 'branches', label: 'Branch Management', icon: IcGitBranch, page: 'BranchManagement', Component: BranchManagement },
  { id: 'org', label: 'Org Setup', icon: IcNetwork, page: 'OrganizationSetup', Component: OrganizationSetup },
  { id: 'brand', label: 'Brand Vault', icon: IcPalette, page: 'BrandVault', Component: BrandVault },
];

export default function CompanySetup({ setPage }) {
  return (
    <TabHub
      icon={IcBuilding2}
      eyebrow="Settings"
      title="Company Setup"
      subtitle="Legal entity, branches, org structure and brand assets"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
